parameters.jsCode:
// Itera sobre cada item que llega al nodo Code
for (const item of items) {

  // --- Línea clave para obtener el nombre dinámico ---
  // Reemplaza 'GetFileInfo' con el nombre de tu nodo.
  // Reemplaza 'nombre_de_tu_campo' con el nombre del campo que contiene el nombre del archivo.
  const nuevoNombreArchivo = $('Get Final Report').first().json['name-report'];

  // Verifica si el item actual tiene datos binarios
  if (item.binary && item.binary.data) {

    // Asigna el nuevo nombre obtenido del nodo anterior
    item.binary.data.fileName = nuevoNombreArchivo;

    // (Opcional) Si el nombre no incluye extensión, puedes añadirla:
    // item.binary.data.fileName = nuevoNombreArchivo + '.pdf';

  } else {
    // (Opcional) Manejo por si un item llega sin binario
    // Puedes ignorarlo o añadir lógica aquí
  }
}

// Devuelve los items con el binario renombrado
return items;

